mapper.select:
SELECT * FROM IMG 
WHERE IMG_TYPE = 'PRODUCT' AND IMG_TYPE_NO = #{productNo} 
ORDER BY IMG_LEVEL

SELECT * FROM IMG 
WHERE IMG_TYPE = 'REVIEW' AND IMG_TYPE_NO = #{reviewNo} 
ORDER BY IMG_LEVEL

SELECT * FROM PRODUCT_OPTION 
WHERE PRODUCT_NO = #{productNo} 
ORDER BY OPTION_NO

SELECT R.*, (SELECT MEMBER_NICK FROM "MEMBER" M WHERE M.MEMBER_NO = R.MEMBER_NO) MEMBER_NICK, (SELECT PROFILE_IMG FROM "MEMBER" M WHERE M.MEMBER_NO = R.MEMBER_NO) MEMBER_PROFILE, (SELECT IMG_PATH||IMG_RENAME FROM IMG I WHERE I.IMG_TYPE_NO = R.REVIEW_TYPE_NO AND I.IMG_TYPE = 'PRODUCT' AND IMG_LEVEL = 0) BUSINESS_THUMBNAIL FROM REVIEW R JOIN PRODUCT P ON(R.REVIEW_TYPE_NO = P.PRODUCT_NO) WHERE REVIEW_TYPE = 'PRODUCT' AND P.PRODUCT_DEL_FL = 'N' AND REVIEW_DEL_FL = 'N'
AND R.REVIEW_TYPE_NO = #{productNo}
ORDER BY REVIEW_NO DESC

SELECT COUNT(*) FROM REPLY R JOIN PRODUCT P ON(R.REPLY_TYPE_NO = P.PRODUCT_NO) JOIN COMPANY_PRODUCT CP ON(P.PRODUCT_NO = CP.PRODUCT_NO) WHERE REPLY_TYPE = 'PRODUCT' AND R.PARENT_REPLY_NO IS NULL AND CP.DELIVERY_FEE IS NOT NULL AND P.PRODUCT_DEL_FL = 'N' AND R.REPLY_DEL_FL = 'N'
AND R.REPLY_TYPE_NO = #{productNo}
AND R.MEMBER_NO = #{loginMemberNo}
AND (R.SECRET_REPLY_STATUS = 'N' OR R.MEMBER_NO = #{loginMemberNo})

SELECT R.*, (SELECT IMG_PATH || IMG_RENAME FROM IMG I WHERE I.IMG_TYPE_NO = R.REPLY_TYPE_NO AND I.IMG_LEVEL = 0 AND I.IMG_TYPE = 'PRODUCT') THUMBNAIL, (SELECT MEMBER_NICK FROM "MEMBER" M WHERE M.MEMBER_NO = R.MEMBER_NO) MEMBER_NICK FROM REPLY R JOIN PRODUCT P ON(R.REPLY_TYPE_NO = P.PRODUCT_NO) JOIN COMPANY_PRODUCT CP ON(P.PRODUCT_NO = CP.PRODUCT_NO) WHERE R.REPLY_TYPE = 'PRODUCT' AND R.PARENT_REPLY_NO IS NULL AND CP.DELIVERY_FEE IS NOT NULL AND P.PRODUCT_DEL_FL = 'N' AND R.REPLY_DEL_FL = 'N'
AND R.REPLY_TYPE_NO = #{productNo}
AND R.MEMBER_NO = #{loginMemberNo}
AND (R.SECRET_REPLY_STATUS = 'N' OR R.MEMBER_NO = #{loginMemberNo})
ORDER BY R.REPLY_NO DESC

mapper.insert:
INSERT INTO PRODUCT_OPTION SELECT SEQ_OPTION_NO.NEXTVAL, A.* FROM (
SELECT #{option.optionName} OPTION_NAME, #{option.productNo} PRODUCT_NO FROM DUAL
) A

mapper.select:
SELECT COUNT(*) FROM IMG 
WHERE IMG_TYPE = #{imageType} 
AND IMG_TYPE_NO = ${imageTypeNo} 
AND IMG_LEVEL IN (${deleteList})

mapper.delete:
DELETE FROM IMG 
WHERE IMG_TYPE = #{imageType} 
AND IMG_TYPE_NO = ${imageTypeNo} 
AND IMG_LEVEL IN (${deleteList})

mapper.update:
UPDATE IMG SET 
IMG_RENAME = #{imageReName}, IMG_ORIGINAL = #{imageOriginal}
WHERE IMG_TYPE = #{imageType} AND IMG_TYPE_NO = ${imageTypeNo} 
AND IMG_LEVEL = ${imageLevel}

mapper.insert:
INSERT INTO ORDER_DETAIL SELECT SEQ_ORDER_DETAIL_NO.NEXTVAL, A.* FROM (
SELECT #{orderDetail.quantity} QUANTITY, #{orderDetail.orderNo} ORDER_NO, #{orderDetail.optionNo} OPTION_NO, #{orderDetail.productNo} PRODUCT_NO, FROM DUAL
) A

mapper.update:
UPDATE REVIEW SET REVIEW_CONTENT = #{reviewContent}, 
REVIEW_STAR = #{reviewStar}, REVIEW_UPDATE_DATE = SYSDATE 
WHERE REVIEW_NO = #{reviewNo}

mapper.insert:
INSERT INTO IMG SELECT SEQ_IMG_NO.NEXTVAL, A.* FROM (
SELECT #{img.imageReName} IMG_RENAME, #{img.imageOriginal} IMG_ORIGINAL, #{img.imageLevel} IMG_LEVEL, #{img.imageType} IMG_TYPE, #{img.imageTypeNo} IMG_TYPE_NO, #{img.imagePath} IMG_PATH FROM DUAL
) A

SELECT SEQ_REPLY_NO.NEXTVAL FROM DUAL
INSERT INTO REPLY VALUES(#{replyNo}, DEFAULT, DEFAULT, #{replyContent}, #{secretReplyStatus}, #{replyType}, #{replyTypeNo}, #{memberNo},
NULL
#{parentNo}
)

